  "meta.gerador_de_prompts_completos_para": "Generatore di prompt completi per dispense, copertine e materiali didattici.",
  "meta.geradorone_gerador_de_prompts": "GeradorOne: Generatore di prompt",
  "meta.ir_para_o_conteudo": "Vai al contenuto",
  "projetos.apostilas_e_capas_salvas_no": "Dispense e copertine salvate sul server. Apri un progetto per riprendere da dove avevi lasciato.",
  "projetos.importar_arquivo_json": "Importa file JSON",
  "prompt.apostila.atencao": "ATTENZIONE: segui rigorosamente tutte le specifiche qui sotto. NON mescolare il tipo di materiale o lo stile visivo con altri non richiesti, NON modificare il formato richiesto e NON presumere informazioni che non sono state fornite.",
  "prompt.apostila.bncc_apenas": "Usa solo i codici BNCC forniti. Non aggiungere codici per inferenza.",
  "prompt.apostila.bncc_sugerir": "Suggerisci abilità della BNCC solo quando c'è una corrispondenza verificabile con la fase scolastica e la componente curricolare. Indica il codice e la descrizione fedele; se non puoi verificare, dichiara il limite e non inventare.",
  "prompt.apostila.extensao.outros": "al massimo {n} pagine",
  "prompt.apostila.extensao.um": "al massimo {n} pagina",
  "prompt.apostila.final": "PRODUCI ORA IL MATERIALE RICHIESTO.",
  "prompt.apostila.h_tarefa": "COMPITO",
  "prompt.apostila.orientacoes": "Indicazioni aggiuntive: {valor}.",
  "prompt.apostila.papel": "AGISCI COME ESPERTO DI EDUCAZIONE, DESIGN ISTRUZIONALE, DIREZIONE ARTISTICA EDITORIALE E PRODUZIONE DI MATERIALE DIDATTICO.",
  "prompt.apostila.s1_adapte": "Adatta linguaggio, esempi, vocabolario e progressione al pubblico.",
  "prompt.apostila.s1_densidade": "Densità del testo: {valor}.",
  "prompt.apostila.s1_escrita": "Stile di scrittura: {valor}.",
  "prompt.apostila.s1_extensao": "Lunghezza obiettivo: {valor}.",
  "prompt.apostila.s1_hipoteses": "Dichiara le ipotesi quando mancano dati indispensabili.",
  "prompt.apostila.s1_objetivo": "Obiettivo di apprendimento: {valor}.",
  "prompt.apostila.s1_profundidade": "Profondità del contenuto: {valor}.",
  "prompt.apostila.s1_publico": "Pubblico di destinazione: {valor}.",
  "prompt.apostila.s1_titulo": "PROFILO PEDAGOGICO",
  "prompt.apostila.s2_bncc": "Codici BNCC indicati: {valor}.",
  "prompt.apostila.s2_ilustrativos": "Distingui esplicitamente i dati illustrativi dai dati misurati, documentati o comprovati.",
  "prompt.apostila.s2_referencia": "Materiale di riferimento obbligatorio:",
  "prompt.apostila.s2_titulo": "CONFIGURAZIONE CURRICOLARE E FONTI",
  "prompt.apostila.s3_1": "Presenta titolo, obiettivi specifici, prerequisiti e un percorso di apprendimento.",
  "prompt.apostila.s3_2": "Organizza sezioni progressive, con spiegazioni complete, definizioni, esempi svolti e applicazioni contestualizzate quando pertinenti.",
  "prompt.apostila.s3_3": "Includi sintesi parziali, domande di verifica e indicazioni chiare di passaggio tra un argomento e l'altro.",
  "prompt.apostila.s3_4": "Concludi con una sintesi generale, attività di consolidamento a difficoltà progressiva e soluzioni commentate.",
  "prompt.apostila.s3_5": "Rispetta la lunghezza obiettivo definita al punto 1 ({extensao}): dimensiona il numero di sezioni, la profondità di ciascuna e la quantità di risorse visive in modo che il materiale completo non superi il limite massimo di pagine di quell'intervallo.",
  "prompt.apostila.s3_6": "Fai una revisione finale di coerenza pedagogica, concettuale, ortografica e visiva.",
  "prompt.apostila.s3_titulo": "ARCHITETTURA DEL MATERIALE",
  "prompt.apostila.s4_estilo": "Stile visivo: {valor}.",
  "prompt.apostila.s4_formato": "Formato prioritario: {valor}.",
  "prompt.apostila.s4_frequencia": "Frequenza: {valor}.",
  "prompt.apostila.s4_hierarquia": "Usa una gerarchia tipografica chiara, spaziatura confortevole, alto contrasto, didascalie e coerenza visiva. Garantisci la leggibilità su schermo e in stampa e non affidarti solo al colore per trasmettere significato.",
  "prompt.apostila.s4_nenhum_recurso": "nessuna risorsa obbligatoria",
  "prompt.apostila.s4_paleta": "Palette: {valor}.",
  "prompt.apostila.s4_personagens": "Non usare figure infantili o personaggi se il pubblico non è infantile. Se ci sono personaggi, devono essere della fascia d'età di {publico}, coerenti con il pubblico di destinazione.",
  "prompt.apostila.s4_prof_visual": "Profondità visiva: {valor}.",
  "prompt.apostila.s4_recursos": "Risorse obbligatorie selezionate: {valor}.",
  "prompt.apostila.s4_titulo": "SISTEMA VISIVO",
  "prompt.apostila.s5_diagramas": "DIAGRAMMI: specifica nodi, frecce, relazioni, direzione di lettura e una versione testuale equivalente. Quando utile, fornisci codice Mermaid valido e semplice.",
  "prompt.apostila.s5_graficos": "GRAFICI: scegli il tipo adatto al confronto. Non fabbricare dati. Se non ci sono dati reali, fornisci solo il modello, i campi necessari e segna ogni esempio come ILLUSTRATIVO.",
  "prompt.apostila.s5_icones": "ICONE: usa un insieme coerente con etichette, senza sostituire un'informazione essenziale solo con simboli.",
  "prompt.apostila.s5_ilustracoes": "ILLUSTRAZIONI: scrivi brief oggettivi con scena, elementi, composizione, inquadratura, stile, palette, diversità e vincoli. Non presumere che l'immagine sia stata generata.",
  "prompt.apostila.s5_infograficos": "INFOGRAFICHE: combina gerarchia, blocchi informativi, icone, numeri e percorso di lettura. Usa solo informazioni presenti o verificabili.",
  "prompt.apostila.s5_intro": "Per ogni risorsa visiva, fornisci: (a) obiettivo pedagogico; (b) posizione suggerita; (c) contenuto esatto; (d) titolo e didascalia; (e) descrizione di produzione; (f) testo alternativo accessibile.",
  "prompt.apostila.s5_linhas": "LINEE DEL TEMPO: includi solo date verificabili e distingui l'ordine didattico dalla cronologia storica.",
  "prompt.apostila.s5_mapas_mentais": "MAPPE MENTALI: crea strutture ricche, con concetto centrale, da 4 a 7 rami principali, sotto-rami, parole chiave brevi, relazioni nominate e una legenda. Evita elenchi lineari camuffati da mappa.",
  "prompt.apostila.s5_quadros": "TABELLE COMPARATIVE: definisci criteri coerenti, intestazioni chiare e note per le eccezioni.",
  "prompt.apostila.s5_titulo": "SPECIFICA DELLE RISORSE VISIVE",
  "prompt.apostila.s6_1": "Scrivi il materiale completo, non solo un sommario.",
  "prompt.apostila.s6_2": "Contrassegna ogni elemento visivo con i blocchi [VISIVO: tipo], [OBIETTIVO], [CONTENUTO], [ISTRUZIONE GRAFICA], [DIDASCALIA] e [TESTO ALTERNATIVO].",
  "prompt.apostila.s6_3": "Per i diagrammi Mermaid, usa blocchi di codice separati. Per i grafici, fornisci una tabella di dati prima della specifica del grafico.",
  "prompt.apostila.s6_4": "Non dichiarare che immagini o grafici sono stati renderizzati se hai solo descritto la loro produzione.",
  "prompt.apostila.s6_5": "Usa le unità del SI e la notazione corretta quando applicabile.",
  "prompt.apostila.s6_titulo": "OUTPUT E MARCATURE TECNICHE",
  "prompt.apostila.s7_1": "Titolo in maiuscolo con l'argomento principale.",
  "prompt.apostila.s7_2": "Riga di supporto: materia | tipo di materiale | pubblico di destinazione.",
  "prompt.apostila.s7_3": "Da 2 a 3 frasi brevi che spiegano cosa capirà il lettore alla fine.",
  "prompt.apostila.s7_4": "Un elenco di 4-6 punti che riassume i concetti chiave, ciascuno di al massimo una riga.",
  "prompt.apostila.s7_titulo": "MICROTESTI OBBLIGATORI DI APERTURA",
  "prompt.apostila.s8_1": "Il tipo di materiale e lo stile visivo richiesti sono stati rispettati, senza mescolarli con altri?",
  "prompt.apostila.s8_2": "La lunghezza è rimasta entro il limite definito al punto 1?",
  "prompt.apostila.s8_3": "Ogni dato, numero, citazione o fonte senza prova è segnato come ILLUSTRATIVO oppure è stato omesso?",
  "prompt.apostila.s8_4": "Ogni risorsa visiva selezionata ha obiettivo pedagogico, posizione, contenuto, didascalia e testo alternativo?",
  "prompt.apostila.s8_5": "La progressione è logica, senza presumere conoscenze non ancora presentate?",
  "prompt.apostila.s8_6": "Non ci sono attività, esercizi o soluzioni oltre a quanto richiesto?",
  "prompt.apostila.s8_7": "Tutto il testo è in italiano, senza errori di revisione?",
